USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetPending @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.TOTAL_ESTIMATED_AMOUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND a.EMPLOYEE_ID=@EmployeeId AND a.IS_ACTIVE=1 WHERE w.CURRENT_STAGE='CONCERN_AUTHORITY' AND w.COMPLETED_DATE IS NULL; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN DECLARE @next VARCHAR(40)=(SELECT r.DESTINATION_AFTER_CONCERN FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.COMPLETED_DATE IS NULL); EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_AUTHORITY','CONCERN_AUTHORITY_APPROVE','CONCERN_AUTHORITY',@next,@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_AUTHORITY','CONCERN_AUTHORITY_RETURN','CONCERN_AUTHORITY','CONCERN_DIVISION',@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'CONCERN_AUTHORITY','IN_WORKFLOW','CONCERN_AUTHORITY_REJECT','REJECTED','END',@Remarks,@BatchReferenceId; END;
GO

